// SPDX-License-Identifier: MIT
pragma solidity 0.8.35;

/// @notice Interface package for the AAC custody milestone.
/// @dev These interfaces are an ABI contract only. They are not deployed
/// implementations and must not be treated as live mint/release permissions.
library AacInterfaceTypes {
    enum AssetKind {
        UsdcLockMint,
        UsdcBurnRelease,
        PaidGb,
        DeveloperToken
    }

    struct ReceiptProof {
        uint256 sourceChainId;
        bytes32 sourceHeader;
        bytes32 receiptsRoot;
        uint64 receiptIndex;
        bytes receiptRlp;
        bytes[] receiptProof;
    }

    struct AacRecord {
        bytes32 aacId;
        AssetKind assetKind;
        uint256 sourceChainId;
        uint256 destinationChainId;
        address sourceGateway;
        address sourceAsset;
        address destinationAsset;
        address recipient;
        uint256 amount;
        bytes32 depositId;
        bytes32 targetDomain;
        bytes32 sourceHeader;
        bytes32 receiptsRoot;
        bytes32 leaf;
        bytes32 proofDigest;
    }
}

/// @notice Verifies source finality and receipt inclusion on the destination
/// chain. A successful call must bind all fields to the same source header.
interface IAacOnchainProofVerifier {
    function verifyFinalizedHeader(
        uint256 sourceChainId,
        bytes32 sourceHeader,
        bytes32 receiptsRoot
    ) external view returns (bool);

    function verifyReceiptProof(
        uint256 sourceChainId,
        bytes32 sourceHeader,
        bytes32 receiptsRoot,
        uint64 receiptIndex,
        bytes calldata receiptRlp,
        bytes[] calldata receiptProof
    ) external view returns (bool);
}

interface IAacReceiptMptVerifier {
    function verifyReceiptProof(
        uint256 sourceChainId,
        bytes32 sourceHeader,
        bytes32 receiptsRoot,
        uint64 receiptIndex,
        bytes calldata receiptRlp,
        bytes[] calldata receiptProof
    ) external view returns (bool);
}

/// @notice The consume-once registry/gateway ABI expected by destination
/// asset adapters.
interface IAacDestinationConsumer {
    function registerVerified(
        AacInterfaceTypes.AacRecord calldata record,
        AacInterfaceTypes.ReceiptProof calldata proof
    ) external returns (bytes32 aacId);

    function consume(bytes32 aacId) external;

    function isConsumed(bytes32 aacId) external view returns (bool);

    function getRecord(bytes32 aacId)
        external
        view
        returns (AacInterfaceTypes.AacRecord memory record);

    function pause() external;

    function unpause() external;
}

/// @notice Common adapter boundary. The adapter must only be callable by the
/// destination consumer and must make the asset effect atomically.
interface IAacAssetAdapter {
    function consumeAac(bytes32 aacId) external;
}

interface IAacPayloadAssetAdapter {
    function consumeAac(bytes32 aacId, bytes calldata effectData) external;
}

/// @notice Canonical CoNET TreasuryBridgeV3 mint adapter.
interface IAacTreasuryMintAdapter is IAacAssetAdapter {}

/// @notice Canonical Base TreasuryBridgeV3 release adapter.
interface IAacTreasuryReleaseAdapter is IAacAssetAdapter {}

/// @notice Canonical paid GBToken mint adapter.
interface IAacPaidGbMintAdapter is IAacAssetAdapter {}

/// @notice Canonical developer-token mint adapter through Peer v5.
interface IAacDeveloperTokenMintAdapter is IAacAssetAdapter {}

/// @notice Role wiring expected by the consumer before custody can open.
interface IAacConsumerRoleConfig {
    function proofVerifier() external view returns (address);
    function treasuryMintAdapter() external view returns (address);
    function treasuryReleaseAdapter() external view returns (address);
    function paidGbMintAdapter() external view returns (address);
    function developerTokenMintAdapter() external view returns (address);
    function admin() external view returns (address);
    function gateway() external view returns (address);
}

AacDestinationConsumerCanary.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.35;

import "./AacHeaderCommitment.sol";
import "./AacDestinationConsumerInterfaces.sol";

interface IAacBaseFinalityV2 {
    function verifyHeader(bytes calldata outputAnchorProof, bytes calldata headerProof)
        external
        view
        returns (AacHeaderCommitment.Commitment memory);
}

interface IAacConetFinalityV2 {
    function verifyHeader(bytes calldata proof)
        external
        view
        returns (AacHeaderCommitment.Commitment memory);
}

/// @notice Paused mainnet canary of the payload-bound consumer.
/// @dev `unpause` is permanently disabled. This address must not receive
/// Treasury, GB, or Peer roles and is not a custody deployment.
contract AacDestinationConsumerCanary {
    enum Status {
        None,
        Verified,
        Consumed
    }

    struct Record {
        bytes32 aacId;
        uint8 assetKind;
        uint256 sourceChainId;
        uint256 destinationChainId;
        address sourceGateway;
        address sourceAsset;
        address destinationAsset;
        address recipient;
        uint256 amount;
        bytes32 depositId;
        bytes32 targetDomain;
        bytes32 sourceHeader;
        bytes32 sourceTxHash;
        bytes32 receiptsRoot;
        uint64 receiptIndex;
        bytes32 leaf;
        bytes32 effectHash;
    }

    address public immutable admin;
    address public immutable gateway;
    address public immutable baseFinalityVerifier;
    address public immutable conetFinalityVerifier;
    address public immutable receiptVerifier;
    bool public paused;
    bool private entered;

    mapping(bytes32 => Record) private records;
    mapping(bytes32 => Status) public statusOf;
    mapping(uint8 => address) public adapters;

    error BadRole();
    error Paused();
    error NotAdmin();
    error NotGateway();
    error AlreadyRegistered();
    error UnknownAac();
    error BadRecord();
    error BadProof();
    error BadEffect();
    error BadAdapter();
    error Reentered();
    error CustodyClosed();

    constructor(
        address admin_,
        address gateway_,
        address baseFinalityVerifier_,
        address conetFinalityVerifier_,
        address receiptVerifier_
    ) {
        if (
            admin_ == address(0) ||
            gateway_ == address(0) ||
            admin_ == gateway_ ||
            baseFinalityVerifier_ == address(0) ||
            conetFinalityVerifier_ == address(0) ||
            receiptVerifier_ == address(0)
        ) revert BadRole();
        admin = admin_;
        gateway = gateway_;
        baseFinalityVerifier = baseFinalityVerifier_;
        conetFinalityVerifier = conetFinalityVerifier_;
        receiptVerifier = receiptVerifier_;
        paused = true;
    }

    function setAdapter(uint8 assetKind, address adapter) external {
        if (msg.sender != admin || adapter == address(0)) revert BadAdapter();
        adapters[assetKind] = adapter;
    }

    function pause() external {
        if (msg.sender != admin) revert NotAdmin();
        paused = true;
    }

    function unpause() external pure {
        revert CustodyClosed();
    }

    function registerBase(
        Record calldata record,
        bytes calldata effectData,
        bytes calldata outputAnchorProof,
        bytes calldata headerProof,
        bytes calldata receiptRlp,
        bytes[] calldata receiptProof
    ) external returns (bytes32) {
        AacHeaderCommitment.Commitment memory header =
            IAacBaseFinalityV2(baseFinalityVerifier).verifyHeader(
                outputAnchorProof,
                headerProof
            );
        return _register(record, effectData, header, receiptRlp, receiptProof);
    }

    function registerConet(
        Record calldata record,
        bytes calldata effectData,
        bytes calldata finalityProof,
        bytes calldata receiptRlp,
        bytes[] calldata receiptProof
    ) external returns (bytes32) {
        AacHeaderCommitment.Commitment memory header =
            IAacConetFinalityV2(conetFinalityVerifier).verifyHeader(finalityProof);
        return _register(record, effectData, header, receiptRlp, receiptProof);
    }

    function consume(bytes32 aacId, bytes calldata effectData) external {
        if (paused) revert Paused();
        if (msg.sender != gateway) revert NotGateway();
        if (entered) revert Reentered();
        if (statusOf[aacId] != Status.Verified) revert UnknownAac();
        Record storage record = records[aacId];
        if (keccak256(effectData) != record.effectHash) revert BadEffect();
        address adapter = adapters[record.assetKind];
        if (adapter == address(0)) revert BadAdapter();
        entered = true;
        statusOf[aacId] = Status.Consumed;
        IAacPayloadAssetAdapter(adapter).consumeAac(aacId, effectData);
        entered = false;
    }

    function getRecord(bytes32 aacId) external view returns (Record memory) {
        return records[aacId];
    }

    function isConsumed(bytes32 aacId) external view returns (bool) {
        return statusOf[aacId] == Status.Consumed;
    }

    function _register(
        Record calldata record,
        bytes calldata effectData,
        AacHeaderCommitment.Commitment memory header,
        bytes calldata receiptRlp,
        bytes[] calldata receiptProof
    ) internal returns (bytes32) {
        if (paused) revert Paused();
        if (msg.sender != gateway) revert NotGateway();
        if (
            record.aacId == bytes32(0) ||
            record.sourceChainId != header.sourceChainId ||
            record.destinationChainId == 0 ||
            record.recipient == address(0) ||
            record.amount == 0 ||
            record.sourceGateway == address(0) ||
            record.sourceAsset == address(0) ||
            record.destinationAsset == address(0) ||
            record.depositId == bytes32(0) ||
            record.targetDomain == bytes32(0) ||
            record.sourceHeader != header.blockHash ||
            record.receiptsRoot != header.receiptsRoot ||
            effectData.length == 0
        ) revert BadRecord();
        if (statusOf[record.aacId] != Status.None) revert AlreadyRegistered();
        if (keccak256(effectData) != record.effectHash) revert BadEffect();
        bool included = IAacReceiptMptVerifier(receiptVerifier).verifyReceiptProof(
            record.sourceChainId,
            record.sourceHeader,
            record.receiptsRoot,
            record.receiptIndex,
            receiptRlp,
            receiptProof
        );
        if (!included) revert BadProof();
        records[record.aacId] = record;
        statusOf[record.aacId] = Status.Verified;
        return record.aacId;
    }
}

